const fs = require('fs');
const path = require('path');

const dir = __dirname;
const input = JSON.parse(fs.readFileSync(path.join(dir, 'input.json'), 'utf8'));

if (typeof input.quantity !== 'number' || typeof input.unitPrice !== 'number') {
  throw new Error('quantity and unitPrice must both be numbers');
}

const total = input.quantity * input.unitPrice;

fs.writeFileSync(
  path.join(dir, 'answer.json'),
  JSON.stringify({ total }, null, 2) + '\n',
  'utf8'
);

console.log(JSON.stringify({ quantity: input.quantity, unitPrice: input.unitPrice, total }));

